insert into passages (title,body,"wordCount",difficulty,topic,status) values ('Cities and Quiet Spaces', 'Modern cities are often described in terms of movement, traffic, and noise. Yet many residents depend on quiet public spaces to read, think, or recover from a demanding day. Parks, libraries, and pedestrian streets can improve urban life not by increasing activity, but by offering a pause from it. This is why planners increasingly view silence and rest as resources rather than luxuries. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 84, 7, 'urban quiet', 'approved');
