insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'Why does the author mention examples in the passage in the passage titled Sleep and Memory for this sleep and memory passage in a northern research briefing context in context 2373.','To make the general claim more concrete.','To show that the topic belongs only to the past.','To distract readers from the main idea.','To prove that examples are always unreliable.','A','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_38", "reading_comprehension", "practice_pool"]'::jsonb,80,'B2',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'Which conclusion is most consistent with the passage in the passage titled Sleep and Memory for this sleep and memory passage in a southern research briefing context in context 2374.','The passage offers no conclusion at all.','The topic should be used with judgment rather than accepted blindly.','The topic has no practical consequences.','The topic should be banned in all cases.','B','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_38", "reading_comprehension", "practice_pool"]'::jsonb,80,'C1',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'What problem does the passage mainly warn against in the passage titled Sleep and Memory for this sleep and memory passage in a central research briefing context in context 2375.','Changing an opinion when facts change.','Using any evidence before making decisions.','Treating a useful idea as if it had no limits.','Reading carefully before responding.','C','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_38", "reading_comprehension", "practice_pool"]'::jsonb,80,'B2',(select max(id) from passages),'approved',false);
insert into passages (title,body,"wordCount",difficulty,topic,status) values ('Public Trust in Science', 'Scientific knowledge changes as new evidence appears, and this can confuse the public. Some people interpret change as weakness, but revision is one of science’s strengths. A claim that can be tested and corrected is more reliable than one that never changes. Public trust depends on understanding that uncertainty and progress often exist together. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 75, 7, 'science', 'approved');
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',7,'Which question is the passage most likely trying to answer in the passage titled Public Trust in Science for this science passage in a online research briefing context in context 2376.','Who invented science in ancient times?','Why should science be ignored completely?','Why is every alternative better than science?','How can science be useful without being treated as a perfect solution?','D','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_38", "reading_comprehension", "practice_pool"]'::jsonb,80,'C1',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',7,'What is the main purpose of the passage in the passage titled Public Trust in Science for this science passage in a evening research briefing context in context 2377.','To explain a balanced view of science.','To describe an unrelated historical event.','To prove that science has no importance.','To advertise a product related to science.','A','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_38", "reading_comprehension", "practice_pool"]'::jsonb,80,'C1',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',7,'Which statement best reflects the author’s attitude toward science in the passage titled Public Trust in Science for this science passage in a summer research briefing context?','It is completely useless in every situation.','It can be valuable, but only when its limits are understood.','It is too simple to deserve serious attention.','It should replace all other approaches immediately.','B','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_38", "reading_comprehension", "practice_pool"]'::jsonb,80,'C1',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',7,'According to the passage, what is one risk connected with science in the passage titled Public Trust in Science for this science passage in a advanced research briefing context?','It removes every possible problem.','People will always become more accurate.','People may overlook an important limitation.','It prevents any kind of improvement.','C','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_38", "reading_comprehension", "practice_pool"]'::jsonb,80,'C1',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',7,'What can be inferred from the passage in the passage titled Public Trust in Science for this science passage in a introductory research briefing context in context 2380.','The author believes simple choices are always wrong.','The passage supports ignoring evidence.','The author rejects all practical solutions.','A careful approach is better than an automatic or extreme response.','D','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_38", "reading_comprehension", "practice_pool"]'::jsonb,80,'C1',(select max(id) from passages),'approved',false);
insert into passages (title,body,"wordCount",difficulty,topic,status) values ('The Role of Difficulty', 'Tasks that are too easy may feel pleasant, but they often produce little growth. Moderate difficulty forces learners to retrieve information, compare options, and notice gaps in understanding. This kind of challenge can be uncomfortable, yet it supports durable learning. The goal is not to make study painful, but to make it demanding enough to be useful. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 78, 7, 'difficulty', 'approved');
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',7,'Which conclusion is most consistent with the passage in the passage titled The Role of Difficulty for this difficulty passage in a coastal education panel context in context 2381.','The topic should be used with judgment rather than accepted blindly.','The topic has no practical consequences.','The passage offers no conclusion at all.','The topic should be banned in all cases.','A','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_39", "reading_comprehension", "practice_pool"]'::jsonb,80,'C1',(select max(id) from passages),'approved',false);
